{
  "compatibility_analysis": [
    {
      "patterns": ["Modular Monolith", "Microservices Architecture"],
      "relationship": "conflicting",
      "rationale": "Both are primary decomposition styles for the same backend: one deploys all capabilities as one unit with in-process module calls and local transactions, the other as independently deployed services owning their data. Applying both to the same capability set at the same time is contradictory. They trade strong local consistency and low footprint (Modular Monolith) against independent scaling and fault isolation (Microservices).",
      "conditions": [
        "They can coexist only as an evolution path or hybrid: a modular monolith core with selected modules (e.g. Notifications or Reporting) extracted as separate services, if module boundaries are kept clean and inter-module calls go through explicit interfaces."
      ],
      "affected_drivers": [
        "Service availability to riders",
        "Timely bike availability and location tracking",
        "Low carbon footprint",
        "Evolution of payment methods and jurisdictions"
      ]
    },
    {
      "patterns": ["Layered Architecture", "Modular Monolith"],
      "relationship": "complementary",
      "rationale": "Modular Monolith gives vertical decomposition by capability; Layered Architecture gives horizontal structure inside each module (API, application, domain, data access). Together they give one enforcement point for data protection per module and keep payment/messaging infrastructure in the lowest layer.",
      "conditions": [
        "Layers are applied within each module, not as one shared data layer that lets modules read each other's tables."
      ],
      "affected_drivers": [
        "Security of user, biometric and payment data",
        "GDPR and regional regulatory compliance",
        "Evolution of payment methods and jurisdictions"
      ]
    },
    {
      "patterns": ["Layered Architecture", "Microservices Architecture"],
      "relationship": "compatible",
      "rationale": "Each microservice can be layered internally. The patterns act at different levels (system decomposition vs. internal structure) and do not interfere.",
      "conditions": [],
      "affected_drivers": [
        "Security of user, biometric and payment data",
        "GDPR and regional regulatory compliance"
      ]
    },
    {
      "patterns": ["API Gateway", "Microservices Architecture"],
      "relationship": "complementary",
      "rationale": "With many services, a gateway gives web and mobile clients one stable entry point, hides service decomposition, and centralizes TLS termination, token validation and rate limiting, so each service does not repeat these controls.",
      "conditions": [
        "The gateway is replicated so it is not a single point of failure for rider flows."
      ],
      "affected_drivers": [
        "Web and mobile client accessibility",
        "Security of user, biometric and payment data",
        "User authentication and session management",
        "Service availability to riders"
      ]
    },
    {
      "patterns": ["API Gateway", "Modular Monolith"],
      "relationship": "conditionally_compatible",
      "rationale": "A single backend does not need routing across services, so the gateway's routing/aggregation role is mostly unused. It remains useful as a security boundary (TLS termination, token validation, rate limiting) in front of the monolith and for both client types.",
      "conditions": [
        "The gateway is justified by cross-cutting security and traffic control, not by routing.",
        "The gateway is kept thin so that it does not duplicate application logic of the monolith."
      ],
      "affected_drivers": [
        "Security of user, biometric and payment data",
        "Web and mobile client accessibility",
        "Low carbon footprint"
      ]
    },
    {
      "patterns": ["API Gateway", "Backend for Frontend (BFF)"],
      "relationship": "conditionally_compatible",
      "rationale": "Both stand between clients and the backend. A BFF can be realized as a client-specific gateway, so combining a general gateway with BFFs can be redundant. They combine coherently when the gateway handles generic edge concerns (TLS, rate limiting, token validation) and the BFFs handle client-specific API shaping.",
      "conditions": [
        "Responsibilities are split: edge security in the gateway, client-specific composition in the BFFs.",
        "If only one of the two is used, it must take over the other's security responsibilities."
      ],
      "affected_drivers": [
        "Web and mobile client accessibility",
        "Security of user, biometric and payment data",
        "Ease of use for all riders"
      ]
    },
    {
      "patterns": ["Backend for Frontend (BFF)", "Modular Monolith"],
      "relationship": "compatible",
      "rationale": "BFFs can call the monolith's module interfaces and adapt them to web (administrator views, history downloads) and mobile (biometric login, scanning, navigation) needs. The BFFs are thin client facades and do not change the monolith's internal decomposition.",
      "conditions": [
        "BFFs contain no business rules; rental and availability logic stays in the monolith modules."
      ],
      "affected_drivers": [
        "Web and mobile client accessibility",
