python3 - <<'PYEOF'
import json
base='/Users/adiazpace/Documents/GitHub/harness-weaver-sandboxes/run-sara-claude-campus-bike-20261029T185144/workspace/_workspace/artifacts/'
drivers=json.load(open(base+'drivers.json'))
driver_names=set(d['name'] for d in drivers['drivers'])

pc=json.load(open(base+'pattern_candidates.json'))
pattern_names=set(p['pattern_name'] for p in pc['pattern_candidates'])

bad=[]
for p in pc['pattern_candidates']:
    for n in p['source_driver_names']:
        if n not in driver_names:
            bad.append(('pattern_candidates',p['pattern_name'],n))

pcomp=json.load(open(base+'pattern_compatibility.json'))
for e in pcomp['compatibility_analysis']:
    for pat in e['patterns']:
        if pat not in pattern_names:
            bad.append(('pattern_compatibility-pattern',e['patterns'],pat))
    for d in e['affected_drivers']:
        if d not in driver_names:
            bad.append(('pattern_compatibility-driver',e['patterns'],d))

alts=json.load(open(base+'alternatives.json'))
alt_ids=set(a['alternative_id'] for a in alts['alternatives'])
for a in alts['alternatives']:
    for pat in a['selected_patterns']:
        if pat not in pattern_names:
            bad.append(('alternatives-pattern',a['alternative_id'],pat))
    for d in a['addressed_drivers']:
        if d not in driver_names:
            bad.append(('alternatives-driver',a['alternative_id'],d))

gaps=json.load(open(base+'stage2_assumptions_gaps.json'))
import re
s1gaps=json.load(open(base+'stage1_assumptions_gaps.json'))
s1ids=set(e['id'] for e in s1gaps['entries'])
for e in gaps['entries']:
    for rid in e['related_ids']:
        if rid.startswith('S1-G') and rid not in s1ids:
            bad.append(('gap-related-id', e['id'], rid))

print("driver_names count", len(driver_names))
print("pattern_names", pattern_names)
print("alt_ids", alt_ids)
print("BAD:", bad)
PYEOF

